    story=f'''<section class="section shell story"><div class="story-media"><img src="{image(c['image2'])}" alt="Ոճային լուսանկար՝ ոչ սրահի աշխատանքը" loading="lazy" width="1000" height="1200"></div><div class="story-copy"><div class="eyebrow">{safe(d['name'])}</div><h2>{safe(c['story'])}</h2><p>Ձեր ցանկալի կերպարը, հարմար ժամը և ծառայության մանրամասները կարելի է քննարկել նախապես։ Ուղարկեք Ձեզ դուր եկած օրինակները կամ պարզապես պատմեք՝ ինչ փոփոխություն եք ցանկանում։</p><p>Սրահը գտնվում է Գյումրիում։ Այցի պայմանները և կոնտակտների արդիականությունը խնդրում ենք ճշտել անմիջապես սրահից։</p><a class="text-link" href="contacts.html">Ծանոթանալ կոնտակտներին{ARROW}</a><p class="photo-note">Լուսանկարը՝ դիզայնի օրինակ, սրահի աշխատանքը չէ։</p></div></section>'''
    invite=f'''<section class="section shell"><div class="panel contact-invite"><div><div class="eyebrow">Ձեր հաջորդ այցը</div><h2>Սկսենք մեկ զրույցից։</h2></div><div><p>Հարցրեք ծառայության մասին, ճշտեք արժեքը և ընտրեք Ձեզ հարմար ժամը՝ անմիջապես սրահի հետ։</p><div class="actions">{button(d)}<a class="text-link" href="contacts.html">Մանրամասներ{ARROW}</a></div></div></div></section>'''
