    service_page=f'''<div class="shell"><section class="page-heading"><div class="eyebrow">{safe(d['name'])} / Ծառայություններ</div><h1>Ընտրեք Ձեր<br>գեղեցիկ պահը։</h1><p>Ցանկը կազմված է սրահի մասին բաց տեղեկությունների հիման վրա։ Ծառայությունների հասանելիությունն ու վերջնական արժեքը համաձայնեցրեք սրահի հետ։</p></section>{service_rows(d)}<section class="section"><div class="section-head"><div><div class="eyebrow">Գեղեցկության տրամադրություն</div><h2>Փոքրիկ ոգեշնչում։</h2></div><p>Այս լուսանկարները ցույց են տալիս կայքի հնարավոր ոճը։ Դրանք սրահի պորտֆոլիոն չեն․ վերջնական տարբերակում կավելացվեն սրահի հաստատած աշխատանքները։</p></div><div class="gallery">{photo(c['image'])}{photo(c['image2'])}</div></section><section class="section faq"><div class="eyebrow">Հաճախ տրվող հարցեր</div><h2>Այցից առաջ։</h2><details><summary>Ինչպե՞ս գրանցվել։</summary><p>Զանգահարեք սրահին կամ օգտվեք նրա սոցիալական էջից։ Այս ցուցադրական կայքը ամրագրումներ չի ընդունում։</p></details><details><summary>Ինչպե՞ս ճշտել գինը։</summary><p>Ընտրած ծառայության արժեքը ճշտեք մասնագետի հետ։ Հաստատված գնացուցակ դեռ չի տրամադրվել։</p></details><details><summary>Ի՞նչը քննարկել նախապես։</summary><p>Ծառայության տեսակը, Ձեր ցանկությունները, հնարավոր ժամը և այցի պայմանները։</p></details></section></div>'''
    (p/'services.html').write_text(page(d,'services',service_page))
