    contacts=f'''<div class="shell"><section class="page-heading"><div class="eyebrow">{safe(d['name'])} / Կապ</div><h1>Ձեր այցը՝<br>մեկ զանգից հեռու։</h1><p>Կապվեք սրահի հետ՝ ծառայության մանրամասները քննարկելու և Ձեր հարմար ժամը համաձայնեցնելու համար։</p></section><section class="section contact-grid"><div><div class="contact-detail"><small>ՀԵՌԱԽՈՍ</small><a href="tel:{d['phone']}" class="phone">{d['phone']}</a></div><div class="contact-detail"><small>ՀԱՍՑԵ</small>{safe(d['address'])}</div>{socialrow}<div class="contact-detail"><small>ԱՇԽԱՏԱՆՔԱՅԻՆ ԺԱՄԵՐ</small>Ճշտեք սրահից՝ զանգահարելով։</div><a class="map-link" href="{mapurl}" target="_blank" rel="noopener">Փնտրել քարտեզում{ARROW}</a></div><div class="panel"><div class="eyebrow">Նախապես պայմանավորվեք</div><h2>Հարցրեք։<br>Ընտրեք։<br>Այցելեք։</h2><p>Ասեք՝ որ ծառայությունն է Ձեզ հետաքրքրում, ինչ օր եք ցանկանում այցելել և ինչ արդյունք եք պատկերացնում։</p><div class="actions">{button(d,'Զանգահարել սրահին')}</div><p class="photo-note">Այցը հաստատվում է անմիջապես սրահի հետ։ Այս էջը ցուցադրական տարբերակ է։</p></div></section><section class="section"><div class="steps"><article class="step"><b>01</b><h3>Ծառայություն</h3><p>Ո՞ր ուղղությունն է Ձեզ հետաքրքրում։</p></article><article class="step"><b>02</b><h3>Արժեք</h3><p>Ի՞նչ է ներառում ծառայությունը։</p></article><article class="step"><b>03</b><h3>Ժամ</h3><p>Ե՞րբ է հարմար Ձեզ այցելել։</p></article></div></section></div>'''
    (p/'contacts.html').write_text(page(d,'contacts',contacts))
